    if (comp.date && fx.phase) h += `<p class="progress-hint">${esc(t('gfocus.compActiveLine', { date: comp.date, days: gmFocusDaysLeft(comp.date), phase: t('gfocus.phase.' + fx.phase), obj: t('gm.obj.' + fx.objective) }))}</p>`;
