    if (boxW) boxW.innerHTML = trainFloatWarmHTML(TRAIN_FLOAT.draft);
    if (boxS) boxS.innerHTML = trainFloatSetsHTML(TRAIN_FLOAT.draft);
    if (boxS || boxW) { trainFloatWireSession(b); trainWireUnitSels(b); }
