    metaLine = `${spec || ex.note ? `<div class="train-float-spec">${esc(spec)}${ex.note ? ` <span class="muted">· ${esc(ex.note)}</span>` : ''}</div>` : ''}${det.length ? `<div class="train-float-sub">${esc(det.join(' · '))}</div>` : ''}`;
