/* Icono de la franja por día de semana DE LA FECHA (índice
   getDay(): 0 domingo … 6 sábado) — dato editable junto al banco:
   domingo 🌙 · lunes 📖 · martes 💡 · miércoles ☀️ · jueves 🌱 ·
   viernes 🧘 · sábado 🤸. */
const SHARE_MSG_ICONS = ['🌙', '📖', '💡', '☀️', '🌱', '🧘', '🤸'];
function shareMsgForDate(iso) {
  if (!SHARE_MSG_BANK.length) return null;
  const [y, m, d] = String(iso || '').split('-').map(Number);
  if (!y || !m || !d) return null;
  const days = Math.floor(Date.UTC(y, m - 1, d) / 86400000);
  const idx = ((days % SHARE_MSG_BANK.length) + SHARE_MSG_BANK.length) % SHARE_MSG_BANK.length;
  const e = SHARE_MSG_BANK[idx] || {};
  const text = (LANG === 'es' ? e.es : e.en) || e.en || e.es || null;
  if (!text) return null;
  return { text, icon: SHARE_MSG_ICONS[new Date(y, m - 1, d).getDay()] || '' };
}
/* REFLEXIÓN SORPRESA (2026-10-27, diseño cerrado de Ronald —
   DISEÑO-DIAS-FUTUROS-Y-REFLEXION-2026-10-27): qué reflexión se
   MUESTRA sigue su propio reloj, independiente del corte contable
   de pendientes: la de un día se revela a las 05:00 locales de ese
   día; entre las 00:00 y las 04:59 se sigue viendo la de AYER (ya
   revelada); un día FUTURO nunca muestra la suya. El banco y su
   rotación por fecha (shareMsgForDate) no cambian: esta función
   solo decide qué fecha se pinta según el momento. */
function shareMsgRevealedFor(iso) {
  const today = todayISO();
  if (!iso || iso > today) return null;
  if (iso === today && new Date().getHours() < 5) return shareMsgForDate(addDaysISO(iso, -1));
  return shareMsgForDate(iso);
}
/* Marca de agua: el icono de la app, cargado una vez (mismo origen)
   y cacheado en memoria junto al resto de recursos de las tarjetas. */
const SHARE_ICON = { img: null, state: 'idle' };
function shareIconEnsure() {
  if (SHARE_ICON.state !== 'idle') return;
  SHARE_ICON.state = 'loading';
  try {
    const im = new Image();
    im.onload = () => { SHARE_ICON.img = im; SHARE_ICON.state = 'ok'; const f = $('share-float'); if (f && f.style.display !== 'none' && SHARE.type === 'workout') shareRender(); };
    im.onerror = () => { SHARE_ICON.state = 'fail'; };
    im.src = 'icons/icon-512.png';
  } catch (e) { SHARE_ICON.state = 'fail'; }
}
/* Fotos de ejercicio de la tarjeta (2026-10-26): caché en memoria
   por URL, mismo patrón que la marca de agua. Se cargan con
   crossOrigin 'anonymous': el host de la biblioteca (GitHub Pages)
   sirve Access-Control-Allow-Origin: *, así la foto entra al lienzo
   SIN contaminarlo (la imagen compartida se sigue pudiendo
   generar); un host sin CORS hace fallar la CARGA — nunca el
   lienzo — y la fila se compone sin foto, sin hueco roto. Al
   terminar de cargar con la hoja abierta, la tarjeta se re-pinta
   sola, como con la marca de agua. */
const SHARE_PHOTOS = {};
function sharePhotoEnsure(url) {
  if (!url || SHARE_PHOTOS[url]) return;
  const rec = SHARE_PHOTOS[url] = { img: null, state: 'loading' };
  try {
    const im = new Image();
    im.crossOrigin = 'anonymous';
    im.onload = () => { rec.img = im; rec.state = 'ok'; const f = $('share-float'); if (f && f.style.display !== 'none' && SHARE.type === 'workout') shareRender(); };
    im.onerror = () => { rec.state = 'fail'; };
    im.src = url;
  } catch (e) { rec.state = 'fail'; }
}
/* Pinta la foto cuadrada (recorte centrado, esquinas redondeadas) y
   devuelve true SOLO si la pintó; si no está lista, dispara la
   carga y devuelve false: la fila se compone con la geometría de
   siempre, sin reservar hueco. */
function sharePhotoDraw(ctx, url, x, y, s) {
  if (!url) return false;
  const rec = SHARE_PHOTOS[url];
  if (!rec) { sharePhotoEnsure(url); return false; }
  if (rec.state !== 'ok' || !rec.img) return false;
  const im = rec.img, iw = im.naturalWidth || im.width, ih = im.naturalHeight || im.height;
  if (!iw || !ih) return false;
  ctx.save();
  ctx.beginPath(); shareRR(ctx, x, y, s, s, Math.max(10, Math.round(s * 0.14))); ctx.clip();
  const sc = Math.max(s / iw, s / ih), dw = iw * sc, dh = ih * sc;
  try { ctx.drawImage(im, x + (s - dw) / 2, y + (s - dh) / 2, dw, dh); } catch (e) { ctx.restore(); return false; }
  ctx.restore();
  return true;
}
