/* ================================================================
 * INSTALABLE PWA (2026-10-25) — registro del service worker y UX de
 * instalación. Todo ADITIVO y defensivo (cada bloque en try/catch):
 * si algo falla aquí, la app sigue funcionando exactamente igual.
 *  - Registro del SW SOLO con feature-detect ('serviceWorker' in
 *    navigator): un Safari viejo sin soporte queda intacto.
 *  - Recarga ÚNICA al tomar el control un SW nuevo, y solo si ya
 *    había controlador (en la primera instalación NO se recarga),
 *    con guarda por versión en sessionStorage contra bucles.
 *  - Botón propio de instalación (beforeinstallprompt) en la
 *    pantalla de acceso y en «Mi perfil»; en iOS Safari, guía breve
 *    (Compartir → «Añadir a pantalla de inicio») descartable con ✕
 *    y recuerdo en localStorage. En modo standalone no se muestra
 *    ninguna llamada a instalar.
 *  - El SW (sw.js) solo cachea la cáscara del mismo origen en modo
 *    RED PRIMERO: Auth/Firestore/Worker jamás pasan por la caché.
 * ================================================================ */
const PWA_SW_VERSION = '20261031-business-perfil';
let pwaDeferredPrompt = null;
function pwaIsStandalone() {
  try {
    return window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
  } catch (e) { return false; }
}
function pwaIsIOSDevice() {
  try {
    const ua = navigator.userAgent || '';
    return /iphone|ipad|ipod/i.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  } catch (e) { return false; }
}
function pwaIsIOSSafari() {
  try {
    const ua = navigator.userAgent || '';
    return pwaIsIOSDevice() && /safari/i.test(ua) && !/crios|fxios|edgios|opios/i.test(ua);
  } catch (e) { return false; }
}
/* NAVEGADORES INTERNOS (2026-10-27, reporte de Ronald con captura
   desde el enlace de Instagram): las apps que abren los enlaces en
   su propio navegador (Instagram, Facebook, WhatsApp, TikTok, LINE,
   Snapchat) NO pueden instalar una PWA — no existe el botón
   Compartir ni «Añadir a pantalla de inicio», y la guía de Safari
   dejaba al usuario nuevo atascado. Devuelve el nombre visible de
   la app o null si es un navegador normal. Detección SOLO por user
   agent; manda sobre las superficies de instalación, donde la
   única salida real es abrir la página en Safari/Chrome. */
function pwaInAppBrowser() {
  try {
    const ua = navigator.userAgent || '';
    if (/instagram/i.test(ua)) return 'Instagram';
    if (/fbav|fban|fb_iab|fbios|fb4a/i.test(ua)) return 'Facebook';
    if (/whatsapp/i.test(ua)) return 'WhatsApp';
    if (/musical_ly|tiktok|bytedancewebview|snssdk/i.test(ua)) return 'TikTok';
    if (/line\//i.test(ua)) return 'LINE';
    if (/snapchat/i.test(ua)) return 'Snapchat';
    return null;
  } catch (e) { return null; }
}
/* Copiar el enlace de la app (variante de navegador interno): vía
   moderna y, si falla, el respaldo clásico de la casa (área de
   texto + execCommand). La confirmación vive en el propio botón:
   «✓ Enlace copiado»; si ni así se pudo, el botón muestra la URL
   para copiarla a mano — jamás un éxito fingido. */
const PWA_APP_URL = 'https://fit.ronbo.store';
async function pwaCopyAppLink(btn) {
  let ok = false;
  try { await navigator.clipboard.writeText(PWA_APP_URL); ok = true; }
  catch (e) {
    try {
      const ta = document.createElement('textarea');
      ta.value = PWA_APP_URL;
      ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      ok = document.execCommand('copy');
      ta.remove();
    } catch (e2) { ok = false; }
  }
  if (btn) {
    btn.textContent = ok ? t('pwa.copied') : PWA_APP_URL;
    setTimeout(() => { try { btn.textContent = t('pwa.copyLink'); } catch (e) {} }, 2600);
  }
  return ok;
}
function pwaGuideDismissed() {
  try { return localStorage.getItem('ronbofit-pwa-guide-dismissed') === '1'; } catch (e) { return false; }
}
function pwaPaintInstall() {
  const standalone = pwaIsStandalone();
  const hasPrompt = !!pwaDeferredPrompt;
  const webview = pwaInAppBrowser();
  /* La guía aparece en Safari iOS y, con su variante de salida, en
     navegadores internos (que jamás instalan: ahí la guía de Safari
     era imposible de seguir). En navegador interno la guía manda
     sobre el botón de instalación si el prompt existiera. */
  const iosGuide = !standalone && (pwaIsIOSSafari() || !!webview);
  /* La guía es la MISMA etiqueta en las dos superficies: se conmuta
     su clave data-i18n (Safari ↔ navegador interno, por plataforma)
     para que applyI18n la repinte bien al cambiar de idioma. */
  const paintGuide = (el) => {
    if (!el) return;
    const key = webview ? (pwaIsIOSDevice() ? 'pwa.webviewTextIos' : 'pwa.webviewTextAndroid') : 'pwa.iosText';
    el.setAttribute('data-i18n', key);
    el.innerHTML = t(key);
  };
  /* Pantalla de acceso: botón (Android/Chrome) o guía (iOS), salvo descarte. */
  const box = document.getElementById('pwa-install-auth');
  if (box) {
    const btn = document.getElementById('pwa-install-btn');
    const guide = document.getElementById('pwa-ios-guide');
    const copy = document.getElementById('pwa-copy-link');
    const showBtn = hasPrompt && !webview;
    const showGuide = !showBtn && iosGuide;
    const showBox = !standalone && !pwaGuideDismissed() && (showBtn || showGuide);
    box.style.display = showBox ? '' : 'none';
    if (btn) btn.style.display = showBox && showBtn ? '' : 'none';
    if (guide) { paintGuide(guide); guide.style.display = showBox && showGuide ? '' : 'none'; }
    if (copy) copy.style.display = showBox && showGuide && webview ? '' : 'none';
  }
  /* «Mi perfil»: fila de estado — botón, guía corta o «instalada». */
  const row = document.getElementById('pwa-profile-row');
  if (row) {
    const btn = document.getElementById('pwa-profile-btn');
    const ios = document.getElementById('pwa-profile-ios');
    const done = document.getElementById('pwa-profile-installed');
    const copy = document.getElementById('pwa-profile-copy');
    const showBtn = !standalone && hasPrompt && !webview;
    const showGuide = !standalone && !showBtn && iosGuide;
    if (btn) btn.style.display = showBtn ? '' : 'none';
    if (ios) { paintGuide(ios); ios.style.display = showGuide ? '' : 'none'; }
    if (copy) copy.style.display = showGuide && webview ? '' : 'none';
    if (done) done.style.display = standalone ? '' : 'none';
    row.style.display = (standalone || showBtn || showGuide) ? '' : 'none';
  }
}
async function pwaDoInstall() {
  if (!pwaDeferredPrompt) return;
  try {
    pwaDeferredPrompt.prompt();
    await pwaDeferredPrompt.userChoice;
  } catch (e) { /* el usuario cerró el diálogo: no pasa nada */ }
  pwaDeferredPrompt = null;
  pwaPaintInstall();
}
(function pwaInit() {
  try {
    const b1 = document.getElementById('pwa-install-btn');
    if (b1) b1.addEventListener('click', pwaDoInstall);
    const b2 = document.getElementById('pwa-profile-btn');
    if (b2) b2.addEventListener('click', pwaDoInstall);
    const close = document.getElementById('pwa-install-close');
    if (close) close.addEventListener('click', () => {
      try { localStorage.setItem('ronbofit-pwa-guide-dismissed', '1'); } catch (e) {}
      pwaPaintInstall();
    });
    const c1 = document.getElementById('pwa-copy-link');
    if (c1) c1.addEventListener('click', () => pwaCopyAppLink(c1));
    const c2 = document.getElementById('pwa-profile-copy');
    if (c2) c2.addEventListener('click', () => pwaCopyAppLink(c2));
    const c3 = document.getElementById('install-card-copy');
    if (c3) c3.addEventListener('click', () => pwaCopyAppLink(c3));
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      pwaDeferredPrompt = e;
      pwaPaintInstall();
    });
    window.addEventListener('appinstalled', () => {
      pwaDeferredPrompt = null;
      pwaPaintInstall();
    });
    pwaPaintInstall();
  } catch (e) { /* la UX de instalación nunca rompe la app */ }
  /* Registro del SW — siempre tras feature-detect. */
  try {
    if ('serviceWorker' in navigator) {
      const hadController = !!navigator.serviceWorker.controller;
      let pwaReloaded = false;
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        if (!hadController || pwaReloaded) return;
        try {
          const key = 'ronbofit-pwa-reloaded-' + PWA_SW_VERSION;
          if (sessionStorage.getItem(key) === '1') return;
          sessionStorage.setItem(key, '1');
        } catch (e) {}
        pwaReloaded = true;
        window.location.reload();
      });
      navigator.serviceWorker.register('sw.js').catch(() => {});
      /* CORRECCIÓN 2026-10-26 (diagnóstico mañana-y-llama): una
         página instalada que nunca se recarga puede quedarse días
         en una versión vieja — iOS reanuda la vista sin recargar y
         la comprobación del SW queda al navegador; todo el mecanismo
         de arriba solo corre cuando la página (re)carga. Al volver
         a primer plano se PIDE la comprobación: si hay un SW nuevo
         en espera/instalándose según el flujo actual, toma el
         control y la recarga única de arriba (con su guarda
         anti-bucle, intacta) deja la app en la versión servida.
         Guarda de ráfaga: como máximo una petición cada 60 s — los
         visibilitychange/pageshow repetidos no la repiten ni pueden
         provocar recargas en bucle (la recarga sigue gobernada solo
         por el controllerchange protegido de arriba). */
      let pwaLastUpdateCheck = 0;
      const pwaCheckUpdate = () => {
        try {
          const now = Date.now();
          if (now - pwaLastUpdateCheck < 60000) return;
          pwaLastUpdateCheck = now;
          navigator.serviceWorker.getRegistration()
            .then(r => { if (r) r.update(); }).catch(() => {});
        } catch (e) {}
      };
      document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') pwaCheckUpdate();
      });
      window.addEventListener('pageshow', pwaCheckUpdate);
    }
  } catch (e) { /* sin SW, la app funciona como siempre */ }
})();

/* ================================================================
 * APP INSTALADA VISIBLE (2026-10-26, piezas A y B del paquete) —
 * la señal de instalación, su marca visible y la cadena de nombre
 * del entrenador en «Mi perfil» la usa renderProfileView.
 *  A. SEÑAL: cuando la app corre en modo instalado/standalone (la
 *     MISMA detección que pinta «✓ App instalada» en el perfil,
 *     pwaIsStandalone), escribe en el documento del PROPIO usuario
 *     — y solo en el suyo — la señal mínima y de forma cerrada
 *       appInstall: { everInstalled: true,
 *                     lastStandaloneAt: serverTimestamp() }
 *     admitida por las reglas en la rama isSelf de users/{uid}.
 *     Se escribe al entrar con sesión si falta y se refresca como
 *     máximo una vez cada 24 h (appInstallShouldWrite): la señal
 *     dice «abierta instalada por última vez el…», no es un
 *     registro de aperturas. Sin modo instalado NO se escribe
 *     nada: la AUSENCIA de señal no afirma «no instalada» (puede
 *     ser navegador, o instalada aún no abierta desde que la
 *     señal existe) — por eso la cara visible sin señal dice
 *     «Sin señal de instalación», nunca «no instalada».
 *  B. MARCA: junto a cada cliente, en «Mis clientes» y en
 *     «Accesos»: insignia «📲 Instalada · {fecha}» si hay señal
 *     (appInstallMarkHtml, en la línea de insignias) o el texto
 *     honesto en la línea atenuada si no la hay
 *     (appInstallNoteHtml). Solo lectura: estas superficies ya
 *     cargan el documento completo del usuario.
 *  Todo en try/catch: la señal y su marca jamás rompen la app.
 * ================================================================ */
const APP_INSTALL_REFRESH_MS = 24 * 3600 * 1000;
let appInstallSignalTried = false;
function appInstallTsMs(v) {
  try {
    if (!v) return 0;
    if (typeof v.toMillis === 'function') return v.toMillis() || 0;
    if (typeof v.toDate === 'function') { const d = v.toDate(); return d ? d.getTime() : 0; }
    if (typeof v.seconds === 'number') return v.seconds * 1000;
    if (typeof v === 'number') return v;
  } catch (e) {}
  return 0;
}
function appInstallShouldWrite(cur, nowMs) {
  if (!cur || cur.everInstalled !== true) return true;
  const last = appInstallTsMs(cur.lastStandaloneAt);
  if (!last) return true;
  return (nowMs - last) >= APP_INSTALL_REFRESH_MS;
}
async function appInstallSignal() {
  if (appInstallSignalTried) return;
  appInstallSignalTried = true;
  try {
    if (!pwaIsStandalone()) return;
    const me = auth.currentUser;
    if (!me) return;
    const cur = (typeof UDATA !== 'undefined' && UDATA) ? (UDATA.appInstall || null) : null;
    if (!appInstallShouldWrite(cur, Date.now())) return;
    await setDoc(doc(db, 'users', me.uid), { appInstall: { everInstalled: true, lastStandaloneAt: serverTimestamp() } }, { merge: true });
  } catch (e) { /* la señal de instalación nunca rompe la app */ }
}
function appInstallDateStr(v) {
  try {
    const ms = appInstallTsMs(v);
    if (!ms) return '';
    return new Date(ms).toLocaleDateString(LANG === 'es' ? 'es-MX' : 'en-US', { day: 'numeric', month: 'short', year: 'numeric' });
  } catch (e) { return ''; }
}
function appInstallMarkHtml(u) {
  try {
    const ai = u && u.appInstall;
    if (ai && ai.everInstalled === true) {
      const d = appInstallDateStr(ai.lastStandaloneAt);
      return ` <span class="ok-badge" title="${esc(t('appinst.last'))}">📲 ${esc(t('appinst.installed'))}${d ? ' · ' + esc(d) : ''}</span>`;
    }
  } catch (e) {}
  return '';
}
function appInstallNoteHtml(u) {
  try {
    const ai = u && u.appInstall;
    if (ai && ai.everInstalled === true) return '';
    return ` · ${esc(t('appinst.noSignal'))}`;
  } catch (e) { return ''; }
}

/* ================================================================
 * MENSAJE FLOTANTE DE INSTALACIÓN (2026-10-26, diseño CERRADO por
 * Ronald — maqueta v4; PERSISTENCIA nueva de la pieza C del
 * paquete «App instalada visible», requisito de Ronald): tarjeta
 * que explica cómo instalar la app como icono (iPhone / Android)
 * y que aparece en la pantalla de acceso y, con la sesión
 * iniciada, sobre la propia app.
 *  - PERSISTENCIA (pieza C): ya NO es «solo primera visita» —
 *    para quien NO corre en modo instalado, la tarjeta aparece en
 *    CADA inicio de sesión (cada carga de la app con o sin sesión
 *    previa, hasta que la app corra instalada). El observador de
 *    Auth la reevalúa al entrar (installCardMaybeShow).
 *  - Dentro de una misma carga se puede cerrar (✕ o
 *    «Entendido»/«Got it») y NO reaparece: el descarte vive SOLO
 *    en memoria (installCardDismissed) — el cierre NO escribe
 *    nada permanente que lo suprima en sesiones futuras. La
 *    marca histórica de localStorage 'ronbofit-install-card-seen'
 *    (la de «primera visita») dejó de mandar: se retira al
 *    iniciar y ya no suprime nada.
 *  - NUNCA en modo standalone (app ya instalada): la detección
 *    local e inmediata de pwaIsStandalone(), sin depender de la
 *    señal del servidor (pieza A). Si llega el evento
 *    'appinstalled' con la tarjeta abierta, se cierra y no
 *    vuelve en esta carga.
 *  - La tarjeta NACE OCULTA en el HTML: si este JS falla, el
 *    acceso queda intacto y jamás bloqueado; todo en try/catch.
 *  - Los textos viven en el diccionario (claves install.*): se
 *    pintan con applyI18n() y se repintan al cambiar el idioma
 *    con la tarjeta abierta, como el resto de la pantalla.
 *  - NAVEGADOR INTERNO (2026-10-27): dentro de Instagram/Facebook/
 *    WhatsApp/TikTok… la tarjeta antepone el «paso 0» de salida al
 *    navegador real (claves install.webviewIos/Android, con el
 *    nombre de la app) y ofrece «Copiar enlace»; los pasos de
 *    Safari/Chrome quedan intactos debajo, porque mandan tras la
 *    salida (installCardPaintVariant).
 * ================================================================ */
let installCardDismissed = false;
function installCardPaintVariant() {
  try {
    const webview = pwaInAppBrowser();
    const step = document.getElementById('install-card-webview-step');
    const txt = document.getElementById('install-card-webview-text');
    const copy = document.getElementById('install-card-copy');
    if (step) step.style.display = webview ? '' : 'none';
    if (txt && webview) {
      const key = pwaIsIOSDevice() ? 'install.webviewIos' : 'install.webviewAndroid';
      txt.setAttribute('data-i18n', key);
      txt.innerHTML = t(key, { app: webview });
    }
    if (copy) copy.style.display = webview ? '' : 'none';
  } catch (e) { /* la variante nunca rompe la tarjeta */ }
}
function installCardMaybeShow() {
  try {
    if (installCardDismissed) return;
    if (pwaIsStandalone()) return;
    installCardPaintVariant();
    const ov = document.getElementById('install-card-overlay');
    if (!ov) return;
    const av = document.getElementById('auth-view');
    const appv = document.getElementById('app-view');
    const visible = (av && av.style.display !== 'none') || (appv && appv.style.display !== 'none');
    if (visible) ov.style.display = 'flex';
  } catch (e) { /* el mensaje de instalación nunca rompe la app */ }
}

