let FAQ_ENTRIES = null;   // entradas vivas del documento (o null)
let FAQ_OPEN_BLOCK = 0;   // bloque desplegado del acordeón (0 = ninguno)
let FAQ_IS_OPEN = false;
function faqEntries() { return (Array.isArray(FAQ_ENTRIES) && FAQ_ENTRIES.length) ? FAQ_ENTRIES : FAQ_SEED; }
function faqSorted(list) { return [...list].sort((x, y) => ((Number(x.block) || 0) - (Number(y.block) || 0)) || ((Number(x.order) || 0) - (Number(y.order) || 0))); }
async function faqLoad() {
  try {
    const s = await getDoc(doc(db, 'app_settings', 'faq'));
    if (s.exists() && Array.isArray(s.data().entries) && s.data().entries.length) FAQ_ENTRIES = s.data().entries;
  } catch { /* sin documento o sin permiso de lectura: manda la semilla */ }
}
/* Las respuestas aprobadas usan **negrita** como único formato. */
function faqRich(txt) { return esc(String(txt == null ? '' : txt)).replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>'); }
function faqIsOpen() { return FAQ_IS_OPEN; }
function renderFaqPanel() {
  const body = $('faq-body'); if (!body) return;
  const L = LANG === 'es' ? 'es' : 'en';
  const list = faqSorted(faqEntries());
  let html = '';
  for (let b = 1; b <= 7; b++) {
    const open = FAQ_OPEN_BLOCK === b;
    html += `<div class="faq-blk"><button type="button" class="faq-blk-t" data-faq-block="${b}" aria-expanded="${open ? 'true' : 'false'}"><span>${b} · ${esc(t('faq.b' + b))}</span><span class="faq-chev" aria-hidden="true">${open ? '▴' : '▾'}</span></button>`;
    if (open) {
      const items = list.filter(e => Number(e.block) === b);
      html += items.length
        ? items.map(e => `<div class="faq-qa"><b>${esc((e.q && (e.q[L] || e.q.en)) || '')}</b><p>${faqRich((e.a && (e.a[L] || e.a.en)) || '')}</p></div>`).join('')
        : `<div class="faq-qa"><p>${esc(t('faq.empty'))}</p></div>`;
    }
    html += '</div>';
  }
  body.innerHTML = html;
  body.querySelectorAll('[data-faq-block]').forEach(btn => { btn.onclick = () => { const b = Number(btn.dataset.faqBlock); FAQ_OPEN_BLOCK = (FAQ_OPEN_BLOCK === b) ? 0 : b; renderFaqPanel(); }; });
}
function faqOpenPanel() { FAQ_IS_OPEN = true; renderFaqPanel(); const bd = $('faq-backdrop'); if (bd) bd.style.display = ''; const p = $('faq-panel'); if (p) p.style.display = ''; }
function faqClosePanel() { FAQ_IS_OPEN = false; const bd = $('faq-backdrop'); if (bd) bd.style.display = 'none'; const p = $('faq-panel'); if (p) p.style.display = 'none'; }
function helpFabSync(tabName) { const f = $('btn-help'); if (f) f.style.display = (tabName === 'track') ? '' : 'none'; const s = $('btn-share-fab'); if (s) s.style.display = (tabName === 'track') ? '' : 'none'; }
/* Cronómetro SOLO en Inicio (decisión de Ronald, correo
   2026-10-28 22:11 CDT): el botón flotante se muestra únicamente
   con la pestaña «Mi registro» (Inicio) activa, para todo usuario
   autenticado según su rol — el mismo patrón que helpFabSync.
   Ocultar el botón NO toca el módulo STOPW: su estado (acc,
   startAt, laps) vive fuera del DOM y el intervalo de swFabPaint
   lo sigue reflejando; al volver a Inicio el botón muestra el
   tiempo en curso tal cual, sin reinicio ni pérdida. */
function swFabSync(tabName) { const f = $('btn-stopwatch'); if (f) f.style.display = (tabName === 'track') ? '' : 'none'; }
/* Tarjeta de metas SOLO en Inicio (orden de Ronald, chat
   2026-10-30 02:10 CDT: «Las metas de hoy solo deben aparecer en
   el botón de inicio! En la pantalla principal»): la tarjeta del
   motor (.goals-card, con «Metas de hoy», el anillo, «Tu objetivo
   con tu cuerpo» y «Tus metas, con fundamento») vive en el flujo
   común de #app-view, FUERA de los paneles — sin este gancho se
   pintaba sobre cualquier pestaña (su captura: Biblioteca con la
   tarjeta entera encima). Espejo de helpFabSync/swFabSync: se
   muestra únicamente con «Mi registro» (Inicio) activa. Ocultarla
   NO toca el motor: render() sigue llamando a renderGoalsEngine()
   y el HTML interno se actualiza igual, así que al volver a Inicio
   el anillo trae el consumo al día sin recargar. */
function goalsCardSync(tabName) { const c = document.querySelector('.goals-card'); if (c) c.style.display = (tabName === 'track') ? '' : 'none'; }
/* ---------- Editor del administrador (Accesos, solo dueño) ---------- */
let FAQ_ED = null;   // borrador editable del editor
async function renderFaqEditorBox() {
  const box = $('faq-editor-box'); if (!box) return;
  if (!(IS_OWNER && ROLE === 'administrador')) { box.innerHTML = ''; return; }
  if (!FAQ_ENTRIES) { try { await faqLoad(); } catch {} }
  FAQ_ED = faqSorted(faqEntries()).map(e => ({ id: e.id, block: Number(e.block) || 1, order: Number(e.order) || 0, q: { en: (e.q && e.q.en) || '', es: (e.q && e.q.es) || '' }, a: { en: (e.a && e.a.en) || '', es: (e.a && e.a.es) || '' } }));
  paintFaqEditor();
}
function paintFaqEditor() {
  const box = $('faq-editor-box'); if (!box || !FAQ_ED) return;
  const blkOpts = sel => { let o = ''; for (let b = 1; b <= 7; b++) o += `<option value="${b}"${b === sel ? ' selected' : ''}>${b} · ${esc(t('faq.b' + b))}</option>`; return o; };
  const rows = FAQ_ED.map((e, i) => `
    <div class="faq-ed-row" data-faq-ed="${i}">
      <div class="faq-ed-top"><b>${esc(e.id)}</b>
        <label>${esc(t('faq.edBlock'))} <select data-f="block">${blkOpts(e.block)}</select></label>
        <label>${esc(t('faq.edOrder'))} <input type="number" data-f="order" value="${e.order}" style="width:64px"></label>
        <span class="faq-ed-btns"><button type="button" class="btn-primary btn-sm" data-faq-save="${i}">${esc(t('form.save'))}</button>
        <button type="button" class="btn-ghost btn-sm" data-faq-del="${i}">${esc(t('faq.edDelete'))}</button></span>
      </div>
      <label class="faq-ed-lab">${esc(t('faq.edQEn'))}</label><input type="text" class="faq-ed-in" data-f="q_en" value="${esc(e.q.en)}">
      <label class="faq-ed-lab">${esc(t('faq.edAEn'))}</label><textarea class="dos-mail-text" data-f="a_en" rows="3">${esc(e.a.en)}</textarea>
      <label class="faq-ed-lab">${esc(t('faq.edQEs'))}</label><input type="text" class="faq-ed-in" data-f="q_es" value="${esc(e.q.es)}">
      <label class="faq-ed-lab">${esc(t('faq.edAEs'))}</label><textarea class="dos-mail-text" data-f="a_es" rows="3">${esc(e.a.es)}</textarea>
    </div>`).join('');
  box.innerHTML = rows + `
    <div class="faq-ed-row">
      <div class="faq-ed-top"><b>+</b>
        <label>${esc(t('faq.edBlock'))} <select id="faq-new-block">${blkOpts(1)}</select></label>
        <span class="faq-ed-btns"><button type="button" class="btn-primary btn-sm" id="faq-new-add">${esc(t('faq.edAdd'))}</button></span>
      </div>
      <label class="faq-ed-lab">${esc(t('faq.edQEn'))}</label><input type="text" class="faq-ed-in" id="faq-new-qen">
      <label class="faq-ed-lab">${esc(t('faq.edAEn'))}</label><textarea class="dos-mail-text" id="faq-new-aen" rows="3"></textarea>
      <label class="faq-ed-lab">${esc(t('faq.edQEs'))}</label><input type="text" class="faq-ed-in" id="faq-new-qes">
      <label class="faq-ed-lab">${esc(t('faq.edAEs'))}</label><textarea class="dos-mail-text" id="faq-new-aes" rows="3"></textarea>
    </div>`;
  box.querySelectorAll('[data-faq-save]').forEach(b => { b.onclick = () => faqEdSave(Number(b.dataset.faqSave)); });
  box.querySelectorAll('[data-faq-del]').forEach(b => { b.onclick = () => faqEdDelete(Number(b.dataset.faqDel)); });
  const add = $('faq-new-add'); if (add) add.onclick = faqEdAdd;
}
function faqEdCollect(i) {
  const row = document.querySelector(`[data-faq-ed="${i}"]`); if (!row || !FAQ_ED || !FAQ_ED[i]) return;
  const g = f => { const el = row.querySelector(`[data-f="${f}"]`); return el ? el.value : ''; };
  FAQ_ED[i].block = Math.min(7, Math.max(1, parseInt(g('block'), 10) || 1));
  FAQ_ED[i].order = parseInt(g('order'), 10) || 0;
  FAQ_ED[i].q.en = g('q_en'); FAQ_ED[i].a.en = g('a_en');
  FAQ_ED[i].q.es = g('q_es'); FAQ_ED[i].a.es = g('a_es');
}
/* AYUDA PÚBLICA — Opción B (diseño DISENO-AYUDA-SIN-LOGIN-
   2026-10-28; autorización de construcción de Ronald por correo
   2026-10-28 21:35 CDT): la copia pública app_settings/faq_public
   alimenta la página /ayuda SIN sesión (delta de reglas: lectura
   anónima SOLO de ese documento; escritura solo del propietario,
   por esta misma vía). La sincronización vive EN el guardado del
   editor: primero la FAQ interna y DESPUÉS la copia; si la copia
   falla, el guardado entero se reporta como error (faq.edError) y
   basta re-guardar — ambas escrituras son setDoc de documento
   completo, así que reintentar nunca duplica ni deja mezcla.
   FAQ_PUBLIC_HIDDEN: entradas que NO salen a la copia pública
   (detalle operativo interno: 2.6 roles y cupos de aprobación;
   3.7 límite de IA por defecto). Quedan solo dentro de la app
   hasta que Ronald diga expresamente que salen; la estructura no
   presupone su decisión — publicarlas mañana es quitar el id de
   esta lista y re-guardar. */
const FAQ_PUBLIC_HIDDEN = ['2.6', '3.7'];
function faqPublicEntries(entries) { return entries.filter(e => !FAQ_PUBLIC_HIDDEN.includes(e.id)); }
async function faqEdPersist() {
  const entries = faqSorted(FAQ_ED).map(e => ({ id: e.id, block: e.block, order: e.order, q: { en: e.q.en, es: e.q.es }, a: { en: e.a.en, es: e.a.es } }));
  await setDoc(doc(db, 'app_settings', 'faq'), { entries, updatedAt: serverTimestamp(), updatedBy: auth.currentUser.uid });
  await setDoc(doc(db, 'app_settings', 'faq_public'), { entries: faqPublicEntries(entries), updatedAt: serverTimestamp(), updatedBy: auth.currentUser.uid });
  FAQ_ENTRIES = entries;
  FAQ_ED = faqSorted(entries).map(e => ({ id: e.id, block: e.block, order: e.order, q: { en: e.q.en, es: e.q.es }, a: { en: e.a.en, es: e.a.es } }));
}
async function faqEdSave(i) { faqEdCollect(i); try { await faqEdPersist(); toast(t('faq.edSaved')); paintFaqEditor(); } catch { toast(t('faq.edError'), true); } }
async function faqEdDelete(i) { if (!window.confirm(t('faq.edConfirmDelete'))) return; FAQ_ED.splice(i, 1); try { await faqEdPersist(); toast(t('faq.edSaved')); paintFaqEditor(); } catch { toast(t('faq.edError'), true); renderFaqEditorBox(); } }
async function faqEdAdd() {
  const g = id => { const el = $(id); return el ? el.value.trim() : ''; };
  const block = Math.min(7, Math.max(1, parseInt(($('faq-new-block') || {}).value, 10) || 1));
  const order = FAQ_ED.filter(e => e.block === block).reduce((m, e) => Math.max(m, e.order), 0) + 1;
  FAQ_ED.push({ id: 'c' + Date.now().toString(36), block, order, q: { en: g('faq-new-qen'), es: g('faq-new-qes') }, a: { en: g('faq-new-aen'), es: g('faq-new-aes') } });
  try { await faqEdPersist(); toast(t('faq.edSaved')); paintFaqEditor(); } catch { toast(t('faq.edError'), true); renderFaqEditorBox(); }
}
{ const hb = $('btn-help'); if (hb) hb.addEventListener('click', faqOpenPanel);
  const xc = $('btn-faq-close'); if (xc) xc.addEventListener('click', faqClosePanel);
  const bd = $('faq-backdrop'); if (bd) bd.addEventListener('click', faqClosePanel);
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && FAQ_IS_OPEN) faqClosePanel(); }); }

/* ============================================================
   CRONÓMETRO DEPORTIVO LIBRE (2026-10-27, diseño
   DISEÑO-CRONOMETRO-DEPORTIVO-2026-10-27, previa aprobada por
   Ronald tal cual). Herramienta a pantalla completa sobre el
   papel tapiz de la marca. Es LIBRE: su estado vive SOLO en
   memoria — no escribe Firestore, ni localStorage, ni toca el
   cronómetro de la sesión del plan (trainChrono*), ni la
   llamita, ni el motor de metas. La precisión sale del reloj
   del sistema (performance.now()): el tiempo se CALCULA desde
   marcas de tiempo en cada pintado, jamás se cuenta por ticks,
   así que no hay deriva aunque el navegador estrangule frames.
   ============================================================ */
const STOPW = { open: false, running: false, startAt: 0, acc: 0, laps: [], raf: 0 };
function swElapsed() { return STOPW.acc + (STOPW.running ? performance.now() - STOPW.startAt : 0); }
function swPad2(n) { return String(n).padStart(2, '0'); }
function swFmtParts(ms) {
  const cs = Math.floor(ms / 10) % 100, s = Math.floor(ms / 1000) % 60, m = Math.floor(ms / 60000);
  return { main: swPad2(m) + ':' + swPad2(s), cs: '.' + swPad2(cs), full: swPad2(m) + ':' + swPad2(s) + '.' + swPad2(cs) };
}
function swLapBase() { return STOPW.laps.reduce((a, l) => a + l.lapMs, 0); }
function swSetBtn(el, label, cls, disabled) {
  if (!el) return;
  el.textContent = label;
  el.className = 'sw-cbtn ' + cls;
  if (disabled) el.setAttribute('disabled', ''); else el.removeAttribute('disabled');
}
function swPaint() {
  const ov = $('sw-overlay'); if (!ov) return;
  const el = swElapsed(), f = swFmtParts(el);
  const main = $('sw-time-main'), csEl = $('sw-time-cs');
  if (main) main.textContent = f.main;
  if (csEl) csEl.textContent = f.cs;
  const st = $('sw-status');
  if (st) {
    if (STOPW.running) { st.textContent = t('sw.running'); st.className = 'sw-status run'; }
    else if (el > 0) { st.textContent = t('sw.paused'); st.className = 'sw-status pause'; }
    else { st.textContent = ''; st.className = 'sw-status'; }
  }
  const sub = $('sw-sub');
  if (sub) {
    if (STOPW.running) sub.innerHTML = esc(t('sw.currentLap')) + ' · <b>' + swFmtParts(el - swLapBase()).full + '</b>';
    else if (STOPW.laps.length) sub.textContent = t(STOPW.laps.length === 1 ? 'sw.totalLaps1' : 'sw.totalLaps', { n: STOPW.laps.length });
    else sub.textContent = '';
  }
  const ring = $('sw-ring');
  if (ring) ring.classList.toggle('sm', STOPW.laps.length > 0);
  const lapsEl = $('sw-laps');
  if (lapsEl) {
    lapsEl.innerHTML = STOPW.laps.map((l, i) =>
      '<div class="lr"><span class="ln">' + esc(t('sw.lapN', { n: i + 1 })) + '</span>' +
      '<span class="lt">' + swFmtParts(l.lapMs).full + '</span>' +
      '<span class="lp">' + esc(t('sw.split')) + '</span></div>').reverse().join('');
  }
  const L = $('sw-btn-left'), M = $('sw-btn-main'), R = $('sw-btn-right');
  if (STOPW.running) {
    swSetBtn(L, t('sw.lap'), 'side', false);
    swSetBtn(M, t('sw.pause'), 'main amber', false);
    swSetBtn(R, t('sw.reset'), 'side', false);
  } else if (el > 0) {
    swSetBtn(L, t('sw.reset'), 'side', false);
    swSetBtn(M, t('sw.resume'), 'main green', false);
    swSetBtn(R, t('sw.lap'), 'side', false);
  } else {
    swSetBtn(L, t('sw.reset'), 'side', true);
    swSetBtn(M, t('sw.start'), 'main green', false);
    swSetBtn(R, t('sw.lap'), 'side', true);
  }
}
function swTick() {
  if (!STOPW.open) { STOPW.raf = 0; return; }
  swPaint();
  STOPW.raf = STOPW.running ? requestAnimationFrame(swTick) : 0;
}
function swKick() { if (STOPW.open && STOPW.running && !STOPW.raf) STOPW.raf = requestAnimationFrame(swTick); }
function swMainAction() {
  if (STOPW.running) { STOPW.acc += performance.now() - STOPW.startAt; STOPW.running = false; }
  else { STOPW.startAt = performance.now(); STOPW.running = true; swKick(); }
  swPaint();
}
function swLapAction() {
  const el = swElapsed(); if (el <= 0) return;
  const prev = swLapBase();
  STOPW.laps.push({ lapMs: el - prev, totalMs: el });
  swPaint();
}
function swResetAction() {
  STOPW.running = false; STOPW.acc = 0; STOPW.startAt = 0; STOPW.laps = [];
  swPaint();
}
function swSideAction(side) {
  if (STOPW.running) { if (side === 'left') swLapAction(); else swResetAction(); }
  else if (swElapsed() > 0) { if (side === 'left') swResetAction(); else swLapAction(); }
}
function swOpenTool() {
  const ov = $('sw-overlay'); if (!ov) return;
  STOPW.open = true;
  ov.style.display = 'block';
  swPaint(); swKick();
}
function swCloseTool() {
  const ov = $('sw-overlay'); if (!ov) return;
  STOPW.open = false;
  if (STOPW.raf) { cancelAnimationFrame(STOPW.raf); STOPW.raf = 0; }
  ov.style.display = 'none';
}
function swRelang() { if (STOPW.open) swPaint(); }
/* Botón redondo flotante (sustituye a la pastilla): refleja el estado
   del cronómetro cuando la herramienta está minimizada — anillo
   pulsante y tiempo vivo si corre; tiempo congelado con ❚❚ si está
   en pausa; nada si está a cero. Solo pinta DOM: no escribe nada. */
let SW_FAB_LAST = '';
function swFabPaint() {
  const fab = $('btn-stopwatch'); if (!fab) return;
  const el = swElapsed();
  let cls = 'sw-fab', txt = '';
  if (STOPW.running) { cls = 'sw-fab live'; txt = swFmtParts(el).main; }
  else if (el > 0) { cls = 'sw-fab paused'; txt = '❚❚ ' + swFmtParts(el).main; }
  if (fab.className !== cls) fab.className = cls;
  const lab = $('sw-fab-time');
  if (lab && SW_FAB_LAST !== txt) { lab.textContent = txt; SW_FAB_LAST = txt; }
}
(function swInit() {
  const fab = $('btn-stopwatch'); if (fab) fab.addEventListener('click', swOpenTool);
  swFabPaint();
  setInterval(() => { if (!STOPW.open) swFabPaint(); }, 250);
  const x = $('sw-close'); if (x) x.addEventListener('click', swCloseTool);
  const M = $('sw-btn-main'); if (M) M.addEventListener('click', swMainAction);
  const L = $('sw-btn-left'); if (L) L.addEventListener('click', () => swSideAction('left'));
  const R = $('sw-btn-right'); if (R) R.addEventListener('click', () => swSideAction('right'));
})();

(function installCardInit() {
  try {
    /* La marca histórica «ya visto» deja de suprimir: se retira. */
    try { localStorage.removeItem('ronbofit-install-card-seen'); } catch (e) {}
    const ov = document.getElementById('install-card-overlay');
    if (!ov) return;
    const close = () => { installCardDismissed = true; ov.style.display = 'none'; };
    const x = document.getElementById('install-card-close');
    if (x) x.addEventListener('click', close);
    const ok = document.getElementById('install-card-ok');
    if (ok) ok.addEventListener('click', close);
    window.addEventListener('appinstalled', close);
    setTimeout(installCardMaybeShow, 650);
  } catch (e) { /* el mensaje de instalación nunca rompe el acceso */ }
})();
